CREATE TABLE live_broker_order(broker_order_id uuid primary key,order_request_id uuid not null unique,strategy_instance_id varchar(120) not null,execution_stock_code varchar(32) not null,side varchar(8) not null,quantity integer not null,client_order_key char(64) not null unique,broker_order_number varchar(64),status varchar(32) not null,payload jsonb not null,created_at timestamp not null default current_timestamp);
CREATE TABLE live_broker_fill(fill_id uuid primary key,broker_order_id uuid not null,order_request_id uuid not null,strategy_instance_id varchar(120) not null,execution_stock_code varchar(32) not null,side varchar(8) not null,fill_quantity integer not null,fill_price numeric(18,2) not null,gross_amount numeric(18,2) not null,fee numeric(18,2) not null default 0,tax numeric(18,2) not null default 0,other_cost numeric(18,2) not null default 0,filled_at timestamp not null,broker_trade_id varchar(128) not null,idempotency_key char(64) not null unique,raw_broker_detail jsonb not null);
CREATE TABLE live_broker_order_audit(audit_id bigserial primary key,event_type varchar(64) not null,broker_order_id uuid,event_time timestamp not null default current_timestamp,detail jsonb not null default '{}'::jsonb);
